describe('Field Validation Error States', () => {
  beforeEach(() => {
    cy.visit('/form');
  });

  it('should display specific validation error for each invalid field when submitting a form', () => {
    // Attempt to submit form with all fields empty
    cy.get('[data-testid="submit-button"]').click();

    // Verify error message for email field
    cy.get('[data-testid="email-error"]').should('be.visible').should('contain', 'Email is required');

    // Verify error message for password field
    cy.get('[data-testid="password-error"]').should('be.visible').should('contain', 'Password is required');

    // Verify error message for username field
    cy.get('[data-testid="username-error"]').should('be.visible').should('contain', 'Username is required');

    // Verify error message for phone field
    cy.get('[data-testid="phone-error"]').should('be.visible').should('contain', 'Phone number is required');

    // Verify form was not submitted
    cy.get('[data-testid="success-message"]').should('not.exist');
  });

  it('should display specific validation error for each invalid field with incorrect formats', () => {
    // Fill username with invalid characters
    cy.get('[data-testid="username-input"]').type('user@invalid');

    // Fill email with invalid format
    cy.get('[data-testid="email-input"]').type('invalid-email');

    // Fill password with too few characters
    cy.get('[data-testid="password-input"]').type('short');

    // Fill phone with invalid characters
    cy.get('[data-testid="phone-input"]').type('abc-def-ghi');

    // Attempt to submit form
    cy.get('[data-testid="submit-button"]').click();

    // Verify specific error for username format
    cy.get('[data-testid="username-error"]').should('be.visible').should('contain', 'Username must contain only letters and numbers');

    // Verify specific error for email format
    cy.get('[data-testid="email-error"]').should('be.visible').should('contain', 'Please enter a valid email address');

    // Verify specific error for password length
    cy.get('[data-testid="password-error"]').should('be.visible').should('contain', 'Password must be at least 8 characters');

    // Verify specific error for phone format
    cy.get('[data-testid="phone-error"]').should('be.visible').should('contain', 'Phone number must be in a valid format');

    // Verify form was not submitted
    cy.get('[data-testid="success-message"]').should('not.exist');
  });
});
